from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def para(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    assert path in by_path, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(by_path[path]['title']) + '</a>'

hub_path = 'web-tech/federated-identity-and-session-lifecycle'
hub_title = 'Federated Identity and Session Lifecycle'
topics = [
 dict(slug='authorization-code-pkce-and-callback-binding', title='Authorization Code, PKCE, and Callback Binding',
 summary='Bind each authorization response to its initiating browser session and one-use code verifier.',
 concept='Authorization code flow moves a short-lived code through the browser, then exchanges it at the token endpoint. PKCE binds that code to a random verifier held by the initiating client. A separate state value binds the redirect response to the login attempt in the current browser session. These controls answer different questions. Neither proves that a returned identity token is valid or that the user can access a local case. For sign-in, use the identity layer above the authorization flow and keep provider configuration fixed on the server. A callback is a new trust boundary, even when it comes from a familiar host.',
 case='The permit portal offers sign-in from two organizations. Reviewer 47 starts at organization 6, opens a second tab for organization 9, and receives callbacks in reverse order. A single global pending-login record would let the later tab consume the earlier state or exchange its code against the wrong issuer. Store each short-lived attempt under its own opaque state, with issuer, redirect URI, verifier, nonce, creation time, and initiating browser-session identity. A callback must match and consume exactly one attempt. If reviewer 47 refreshes a used callback URL, it fails cleanly instead of creating a second app session.',
 implementation='Generate a high-entropy verifier and state using a cryptographic random source. Send the S256 challenge in the authorization request and retain the verifier in server-held, short-lived attempt state where the architecture permits. Bind the attempt to the same browser session that initiated it. On callback, reject missing, expired, consumed, or mismatched state before exchanging the code. Select the configured token endpoint from the stored issuer, never from a callback parameter. Use the exact registered redirect URI and client configuration. Protect the attempt store against concurrent consumption with an atomic delete or compare-and-swap. Handle error callbacks without echoing codes or tokens into logs, analytics, or user-visible text. After exchange, verify the identity token separately before creating a local session.',
 cost='One attempt record adds O(1) server storage and a short expiry; an atomic consume adds a storage round trip. Multiple pending tabs require one record per attempt rather than a single cookie slot. The token exchange adds network latency and can fail independently of the authorization redirect. Retrying a used code is generally not a recovery strategy. Measure callback rejection categories without storing the raw code or verifier, plus issuer mismatch, state expiry, and token-endpoint latency. Remove abandoned attempts on expiry. A server session may cost storage, but it also gives the application a place to revoke and audit access after the external exchange.',
 failure='Replay the same callback twice and confirm only the first attempt can consume state. Start two provider attempts in separate tabs, complete them out of order, and verify each binds to its own issuer and verifier. Replace the returned state, omit it, or age the attempt past its deadline; no token exchange should occur. Swap the configured redirect URI or send a code from a different issuer and reject the exchange. A successful HTTP response from the token endpoint is not enough: a malformed or wrongly addressed identity token must still fail the next boundary.',
 drill='Create 47 pending attempts across two issuer configurations, each with a random state and verifier. Complete one normal callback, one replay, one expired callback, and two out-of-order tab callbacks. Count exchanges and assert that only valid, unconsumed attempts reached the token endpoint. Seed logs with a test code and verifier, run the flow, then search logs and traces to prove neither value was copied. Document which process owns expiry and what the user sees when an old tab returns.',
 decision='A callback belongs to one initiating attempt; successful exchange alone does not establish a local identity.',
 code='function mayExchangeCallback(callback, attempt, browserSessionId, now) {\n  return Boolean(attempt) && !attempt.consumed &&\n    callback.state === attempt.state &&\n    browserSessionId === attempt.browserSessionId && now < attempt.expiresAt;\n}\nconsole.log(mayExchangeCallback({ state: "state-47" }, { state: "state-47", browserSessionId: "session-6", consumed: false, expiresAt: 90 }, "session-9", 63));\n// Output: false',
 checks=['State and verifier have separate purposes and are generated afresh.', 'A callback consumes one matching browser-session attempt.', 'Issuer and redirect configuration come from trusted attempt state.'],
 mistakes=['Reusing one pending-login slot across tabs.', 'Treating PKCE as a substitute for state or identity-token verification.', 'Logging the code, verifier, or full callback URL.'],
 related=['web-tech/federated-login-callback-boundary','web-tech/identity-and-application-security']),
 dict(slug='id-token-verification-and-stable-account-identity', title='ID Token Verification and Stable Account Identity',
 summary='Verify signed identity claims and key local accounts by issuer plus subject, not mutable email.',
 concept='An identity token is a signed assertion from a configured identity provider to a specific client. Its claims are input to a local account mapping only after cryptographic and contextual verification. The stable external key is the pair of issuer and subject. An email can change, be recycled, be absent, or carry different verification semantics across providers. Matching local accounts by email alone can hand one person another person’s history. The app still owns its own roles, tenant membership, and record permissions; external sign-in establishes identity, not a blanket grant to local resources.',
 case='The permit portal stores reviewer 47 under a verified work address. An external provider later returns that same address with a different subject for a new employee. Email auto-match would attach the newcomer to reviewer 47’s cases. The app instead searches the exact issuer-and-subject pair and finds no existing link. It offers an approved enrollment path without revealing whether the email owns an account. A separate token from the correct subject but intended for another client application also fails because its audience does not include this app. The name shown on the page may update; the subject key does not silently change.',
 implementation='Use a maintained identity-token verifier for the configured issuer. Verify its signature against that issuer’s trusted keys and an allowed algorithm; reject a token that only decodes successfully. Require the exact issuer, expected audience, valid time window, and nonce when the flow sent one. Handle multi-audience client and authorized-party conditions according to the chosen protocol profile. Use the issuer and subject together as a unique database key. Treat email, display name, picture, and group claims as profile data requiring separate policy and freshness decisions. A successful verification may create or load a local account, but resource access still checks current tenant membership. Do not accept arbitrary key URLs or issuer metadata supplied by a browser request. Plan for provider key rotation without making signature failure a silent success.',
 cost='Cryptographic verification is effectively O(1) per token for fixed-size claims, plus cached-key lookup and occasional key-set refresh. A remote key fetch on every login increases latency and makes the app brittle during provider outages. A unique compound index on issuer and subject keeps account lookup efficient. Group claims can be large and stale; copying them into local authorization without a refresh rule creates hidden revocation delay. Measure verification failure categories, key-refresh behavior, duplicate-link attempts, and time from external membership removal to local denial. Keep diagnostic events coarse enough not to expose raw tokens or profile data.',
 failure='Present a token with a valid-looking JSON body but no valid signature; reject it. Repeat with wrong audience, wrong issuer, expired time, and nonce from another tab. Change the email while keeping issuer and subject; the existing local account remains the same. Reuse the email with a new subject; no automatic account merge occurs. Rotate signing keys and confirm a valid new-key token succeeds only through trusted issuer key discovery. Remove a user’s local tenant membership after sign-in and verify access is denied even if the identity token remains valid.',
 drill='Create two issuer configurations, two subjects that report the same email, and a local account for only one pair. Feed the verifier signed fixtures for correct and wrong audiences, expiry, nonce, and key rotation. Record the local account selected for each accepted token. Then remove case-47 access and try a direct case request with an active app session. Count account-mapping decisions and authorization decisions separately; a single “login passed” test misses the later boundary.',
 decision='Accept identity only from a verified issuer-to-client assertion, then apply local permission policy.',
 code='function externalIdentityKey(verifiedClaims) {\n  if (!verifiedClaims.issuer || !verifiedClaims.subject) throw new Error("Missing identity key");\n  return JSON.stringify([verifiedClaims.issuer, verifiedClaims.subject]);\n}\nconsole.log(externalIdentityKey({ issuer: "issuer-6", subject: "reviewer-47", email: "shared@permit.test" }) === externalIdentityKey({ issuer: "issuer-6", subject: "reviewer-62", email: "shared@permit.test" }));\n// Output: false',
 checks=['Signature, issuer, audience, time, and flow nonce are verified by a trusted verifier.', 'Local mapping uses issuer plus subject.', 'Local record permission remains separate from sign-in.'],
 mistakes=['Parsing token JSON without verifying its signature.', 'Using email as the unique federated identity key.', 'Turning a provider group claim directly into permanent local access.'],
 related=['web-tech/object-level-authorization-for-reads-and-writes','web-tech/passkey-registration-challenge-and-credential-binding']),
 dict(slug='refresh-token-rotation-and-app-session-boundary', title='Refresh Token Rotation and App Session Boundary',
 summary='Keep external token renewal separate from revocable browser sessions and handle rotation races.',
 concept='A browser session for the application and tokens issued by an external identity provider serve different systems. The app session should carry only the identity and policy state needed for this app, with a revocation path. Refresh tokens extend access to a provider and therefore need stricter custody than a short-lived page request. Public clients require a suitable replay defense, such as rotation or sender constraint under their provider profile. A server-backed application can keep provider tokens out of browser-readable storage and issue a secure, HttpOnly app-session cookie instead. None of these choices removes the need for current local authorization.',
 case='Reviewer 47 opens three tabs. Their access token expires while all three tabs request case lists. If each tab independently uses the same rotating refresh token, one succeeds and the others may trigger reuse detection. A server-owned session coordinates one refresh per token family and makes the other requests wait for the result or fail with a recoverable sign-in state. When the reviewer signs out, the portal invalidates its own session immediately. A provider token may remain valid briefly unless the provider supports revocation, so the app does not present local logout as proof that every external session ended.',
 implementation='Choose a token custody model before coding. For a server-backed app, store provider tokens encrypted or otherwise protected server-side with access control and limited retention; send the browser a session cookie with Secure, HttpOnly, and an appropriate SameSite policy. Rotate the app session identifier at sign-in and account changes. Serialize refresh for each token family using a lock or compare-and-swap; persist a replacement token atomically before releasing waiting requests. Reject a spent token replay according to the provider contract and decide when to invalidate the family. For a public client, follow the provider’s required rotation or sender-bound design and understand that browser script compromise remains a different risk. Keep local permission checks fresh on private API reads and writes.',
 cost='One refresh usually costs a provider round trip; repeated concurrent refresh can multiply traffic and cause failed sessions. Per-family coordination adds contention but keeps normal case requests from racing on a one-use token. Session lookup costs O(1) with indexed identifiers, while server-side storage and cleanup grow with active sessions. Shorter access-token lifetimes increase renewal frequency; longer lifetimes increase the delay before external scope changes take effect unless resource servers recheck. Track refresh attempts per session, rotation conflicts, replay detections, sign-out-to-denial time, and provider outages. Never use raw tokens as telemetry labels.',
 failure='Expire the access token and send 47 concurrent requests from several tabs. Only one refresh should consume the current rotating token; the others should receive a consistent new session outcome. Crash after provider success but before storing the replacement and verify the app fails closed with a sign-in recovery path. Replay a spent refresh token and confirm the chosen family response. Sign out in one tab, wake another, and deny its private API request. Remove a reviewer from a tenant while the provider token remains valid; local authorization must still reject the case.',
 drill='Build a session store for reviewer 47 with a provider token family and a local permission version. Inject 47 simultaneous requests at expiry, one provider timeout, one replay, and a sign-out race. Record provider calls, issued app sessions, and rejected stale requests. Inspect cookies for Secure, HttpOnly, and SameSite attributes in a real browser environment. Switch the browser to reviewer 62 and check that neither old account caches nor an old session can reveal case 47.',
 decision='The application owns its session and authorization lifetime; provider renewal is a separate protected operation.',
 code='function sessionMayReadCase(session, account) {\n  return Boolean(session) && !session.revoked &&\n    session.accountId === account.id &&\n    session.permissionVersion === account.permissionVersion;\n}\nconsole.log(sessionMayReadCase({ accountId: 47, permissionVersion: 3, revoked: false }, { id: 47, permissionVersion: 4 }));\n// Output: false',
 checks=['Provider tokens are held under a deliberate custody model.', 'Concurrent refresh cannot consume one rotating token multiple times.', 'Local sign-out and permission revocation deny private requests.'],
 mistakes=['Keeping long-lived provider refresh tokens in routine browser-readable storage.', 'Allowing each tab to rotate the same token independently.', 'Treating provider token expiry as the app’s only revocation mechanism.'],
 related=['web-tech/permission-revocation-and-active-sessions','web-tech/browser-storage-cleanup-on-account-change']),
 dict(slug='federated-account-linking-logout-and-revocation', title='Federated Account Linking, Logout, and Revocation',
 summary='Require an explicit signed-in linking ceremony and distinguish local logout from provider logout.',
 concept='Adding another sign-in provider to an existing account is a sensitive account change. It should start from a current authenticated app session, require deliberate user intent, and complete through a fresh verified provider callback. The newly verified issuer-and-subject pair must be unique across local accounts. A matching email is not consent to merge histories. Unlinking can strand a user without a recovery method, so policy must confirm another usable sign-in path before removal. Logout is similarly layered: clearing an app session does not necessarily end the identity provider’s browser session or revoke every issued token.',
 case='Reviewer 47 wants to add a second work identity. A different reviewer, 62, already has an account with the same email alias at that provider. The link flow returns a verified subject belonging to reviewer 62. The portal refuses to move or merge it automatically and records a safe conflict without revealing the other account’s cases. Later reviewer 47 signs out while the provider still has an active browser cookie. The app invalidates its own session and clears account-scoped private UI state immediately; if the product supports provider logout, it initiates that distinct protocol and explains that other provider sessions or devices may remain.',
 implementation='Begin linking only after recent app authentication where risk warrants it. Store the target local account ID, initiating session, provider issuer, state, verifier, and expiry in one-use server state. On callback, verify the identity assertion, then inside a transaction enforce uniqueness of the issuer-and-subject pair and confirm the initiating app account is still current. Require a user-facing confirmation before changing the account’s sign-in methods. Log a minimal audit event without raw tokens. On unlink, check for another usable credential or a defined recovery path, then revoke sessions if policy requires it. For logout, invalidate the local server session and clear private browser state regardless of whether remote logout succeeds. Provider-wide sign-out or token revocation needs supported endpoints and separate success reporting.',
 cost='A unique link lookup is O(log N) with an index over N external identities; transaction cost is small relative to the damage of a wrong merge. Recent-authentication prompts add friction and should match account risk. Calling provider logout or revocation adds network latency and may be unavailable or partial, so local session invalidation must not wait for it. Audit and notification retention carry privacy costs. Measure link conflicts, abandoned ceremonies, last-method unlink denials, local sign-out-to-denial time, and remote logout failures without retaining subject identifiers in broad analytics.',
 failure='Start a link flow from reviewer 47, sign out, then complete its callback under reviewer 62’s session; reject it. Try to link an issuer-and-subject pair already owned by another local account; the unique constraint and application response must both block the merge. Attempt to unlink the last usable method and require a recovery decision. Force remote logout to time out while local logout succeeds; private case requests still fail. Use the browser back button after logout and confirm cached case content does not appear as an active signed-in page.',
 drill='Create local accounts 47 and 62. Give them the same email alias but different provider subjects, then try to link reviewer 62’s subject to account 47. Verify conflict handling and that neither account’s case list changes. Complete a valid link from a fresh session, sign out, and simulate provider logout failure. Retry a protected request, a restored page, and an old tab. Remove the linked identity only after confirming another usable credential. Record what local and remote logout each actually achieved.',
 decision='Account links require verified identity and current local intent; logout reports only the sessions it actually ended.',
 code='function mayLinkIdentity(activeAccountId, ceremony, externalIdentity) {\n  return ceremony.accountId === activeAccountId && !ceremony.consumed &&\n    externalIdentity.verified && !externalIdentity.ownerAccountId;\n}\nconsole.log(mayLinkIdentity(47, { accountId: 47, consumed: false }, { verified: true, ownerAccountId: 62 }));\n// Output: false',
 checks=['Linking is bound to a current app session and fresh provider assertion.', 'An external subject cannot belong to two local accounts.', 'Local logout denies access even if provider logout fails.'],
 mistakes=['Auto-merging accounts because their emails match.', 'Leaving a stale linking callback valid after account switch.', 'Claiming local logout revoked every provider session.'],
 related=['web-tech/account-recovery-and-session-revocation','web-tech/browser-storage-cleanup-on-account-change']),
]

assert len(topics) == 4 and hub_path not in by_path
hub = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
hub.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + hub_path)), path=hub_path,
           title=hub_title, summary='Bind provider callbacks, verify identity, renew sessions, and control account links and logout.',
           sort_order=3200, created_at=stamp, updated_at=stamp, published_at=stamp)
hub['data'] = {'subject_root':'web-tech/web-technology','section_path':hub_path,'content_format':'html','seo_ready':False,
               'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},
               {'title':'Projects','path':'web-tech/web-technology/project'}, {'title':'Quizzes','path':'web-tech/quizzes'}]}
